package com.agriconnect.rescue;import java.time.Duration;import java.util.UUID;import org.slf4j.MDC;import org.springframework.context.annotation.*;import org.springframework.http.client.SimpleClientHttpRequestFactory;import org.springframework.web.client.RestClient;@Configuration class InternalRestConfig{@Bean RestClient.Builder restClientBuilder(){var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(Duration.ofSeconds(2));f.setReadTimeout(Duration.ofSeconds(5));return RestClient.builder().requestFactory(f).requestInterceptor((request,body,execution)->{String id=MDC.get("traceId");request.getHeaders().set("X-Trace-Id",id==null?UUID.randomUUID().toString():id);return execution.execute(request,body);});}}
